// Normalize phone -> wa_id and build retry payload per row.
function toWaId(raw) {
  if (!raw) return null;
  let d = String(raw).replace(/\D/g, '');
  if (!d) return null;
  if (d.length === 11 && d.startsWith('0')) d = d.slice(1);
  if (d.length === 10) d = '91' + d;
  if (d.length < 11 || d.length > 15) return null;
  return d;
}
function firstName(name) {
  const t = (name ?? '').trim();
  return t ? t.split(/\s+/)[0] : 'there';
}
const out = [];
for (const item of $input.all()) {
  const r = item.json;
  const waId = toWaId(r.customer_phone);
  if (!waId) continue;
  const orderRef = r.order_number;
  out.push({
    json: {
      payload: {
        wa_id: waId,
        name: firstName(r.customer_name),
        order_ref: orderRef,
        total: String(r.total_price ?? ''),
        sent_by: 'journey:order_confirmation:' + orderRef,
      },
    },
  });
}
return out;

